import { createHash } from "node:crypto";
import { readFile, writeFile } from "node:fs/promises";
import { fileURLToPath, pathToFileURL } from "node:url";
import { dirname, join } from "node:path";

const directory = dirname(fileURLToPath(import.meta.url));
const workerPath = join(directory, "worker.js");
const adapterPath = join(directory, "github-app-adapter.js");
const outputPath = join(directory, "worker.bundle.js");
const workerImport = /^import \{ createGitHubAppClient \} from ["']\.\/github-app-adapter\.js["'];\r?\n\r?\n/;
const stripNamedExports = (source) =>
  source.replace(/^export\s+(?=(?:const|class|async function|function)\b)/gm, "");

export async function buildEditorBundle() {
  const [workerSource, adapterSource] = await Promise.all([
    readFile(workerPath, "utf8"),
    readFile(adapterPath, "utf8"),
  ]);
  if (!workerImport.test(workerSource)) {
    throw new Error("worker.js adapter import did not match the expected static import");
  }
  const workerBody = stripNamedExports(workerSource.replace(workerImport, ""));
  const adapterBody = stripNamedExports(adapterSource);
  if (/^\s*export\s/m.test(adapterBody)) {
    throw new Error("Adapter still contains an export after bundle transformation");
  }
  const sourceHash = createHash("sha256")
    .update(workerSource)
    .update("\0")
    .update(adapterSource)
    .digest("hex");
  return [
    `// Generated by build-editor-bundle.mjs; do not edit. Source SHA-256: ${sourceHash}`,
    "const createGitHubAppClient = (() => {",
    adapterBody,
    "  return createGitHubAppClient;",
    "})();",
    workerBody,
  ].join("\n");
}

async function main() {
  const bundle = await buildEditorBundle();
  if (process.argv.includes("--check")) {
    let existing;
    try {
      existing = await readFile(outputPath, "utf8");
    } catch {
      throw new Error("worker.bundle.js is missing; run node tools/watchdog/build-editor-bundle.mjs");
    }
    if (existing !== bundle) {
      throw new Error("worker.bundle.js is out of date; regenerate it before testing or deployment");
    }
    console.log("worker.bundle.js matches worker.js and github-app-adapter.js");
    return;
  }
  await writeFile(outputPath, bundle, "utf8");
  console.log(`Wrote ${outputPath}`);
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main().catch((error) => {
    console.error(error.message);
    process.exitCode = 1;
  });
}
